<template>
	<view>
		<u-sticky>
			<view class="pt-20 pb-20" style="background: #F4F5F7;">
				<view class="box_1 d-flex a-center j-center" @click="routerTo('/pagesE/addXiChe/addXiChe')">
					<image src="../static/icon14.png" mode=""></image>
					<span class="ml-16">新增套餐</span>
				</view>
			</view>

		</u-sticky>

		<empty v-if="list.length==0"></empty>
		<view class="box_2 " v-for="(item,index) in list" :key="index">
			<view class="d-flex a-center j-sb">
				<view class="box_2_title ">
					{{item.name}}
				</view>
				<view class="d-flex a-center">
					<u-icon @click="routerTo('/pagesE/addXiChe/addXiChe?item='+JSON.stringify(item))" name='edit-pen'
						size="24"></u-icon>
					<view class="ml-10" @click="delCategoryApi(item.id)">
						<u-icon name='minus-circle-fill' color="red" size="22"></u-icon>
					</view>
				</view>
			</view>
			<view class="d-flex a-center j-sb mt-10">
				<view class="f-size-24 f-blod">
					次数： <span class="color-03 f-500">{{item.number}}次</span>
				</view>
				<view class="f-size-24 color-03">
					￥{{item.price}}
				</view>
			</view>


		</view>

	</view>
</template>

<script>
	export default {
		data() {
			return {
				show: false,
				glshow: false,
				name: "",
				list: [],
				category_id: '',
				editname: '',
				page: 1

			};
		},
		onLoad() {
			this.categoryListApi()
		},
		onShow() {
			this.categoryListApi()
		},
		onReachBottom() {
			this.page++
			this.categoryListApi(1)
		},
		methods: {
			async delCategoryApi(id) {
				let res = await this.delwash_car({
					id
				})
				if (res.code == 1) {
					this.list.forEach((item, index) => {
						if (item.id == id) {
							this.list.splice(index, 1)
						}
					})
					this.$forceUpdate()
				}
			},

			async categoryListApi(e) {
				if (e !== 1) {
					this.page = 1
				}
				let res = await this.wash_carList({
					page: this.page
				})
				if (res.code == 1) {
					if (e == 1) {
						this.list = [...this.list, ...res.data]
					} else {
						this.list = res.data
					}
				}
			}
		}
	}
</script>

<style lang="scss">
	page {
		padding: 0rpx 0;
		box-sizing: border-box;
		background: #F4F5F7;
	}

	.box_1 {

		width: 690rpx;
		height: 74rpx;
		background: #fff;
		border-radius: 10rpx;
		font-weight: 500;
		font-size: 32rpx;
		color: #3D3D3D;
		text-align: center;
		margin: 0rpx auto;
		padding: 16rpx 0;
		box-sizing: border-box;

		image {
			width: 36rpx;
			height: 36rpx;
		}
	}

	.box_2 {
		padding: 20rpx 30rpx;
		box-sizing: border-box;
		background-color: #fff;
		margin-bottom: 30rpx;

		.del-img {
			width: 34rpx;
		}

		.box_2_title {
			font-weight: 600;
			font-size: 28rpx;
			color: #3D3D3D;

		}

		.box_2_card {
			font-weight: 600;
			font-size: 24rpx;
			color: #036045;
		}

	}

	.ipt_box {
		width: 690rpx;
		height: 90rpx;
		background: #F8F9FC;
		border-radius: 16rpx 16rpx 16rpx 16rpx;
		padding: 22rpx 30rpx;
		box-sizing: border-box;
		margin: 60rpx 0 100rpx;
	}

	.pop_box {
		width: 750rpx;
		height: 544rpx;
		background: #FFFFFF;
		border-radius: 40rpx 40rpx 0rpx 0rpx;
		padding: 32rpx;
		box-sizing: border-box;

		.ipt_btn {
			width: 690rpx;
			height: 102rpx;
			background: #036045;
			border-radius: 1246rpx 1246rpx 1246rpx 1246rpx;
			text-align: center;
			line-height: 102rpx;
			font-size: 28rpx;
			color: #FFFFFF;
		}
	}
</style>